  const validateCreate=()=>{const errors:Record<string,string>={};if(form.displayName.trim().length<2)errors.displayName="Display name must be at least 2 characters";if(form.organization.trim().length<2)errors.organization="Organization must be at least 2 characters";if(!/^did:[a-z][a-z0-9]*:[A-Za-z0-9._\-]+$/.test(form.did.trim()))errors.did="Invalid DID format (expected did:method:identifier, e.g. did:sampraan:operator-42)";setFormErrors(errors);return Object.keys(errors).length===0;};
